package com.example.payment;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import tools.jackson.databind.ObjectMapper; import java.math.BigDecimal; import java.net.URI; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/payments") public class PaymentController {
 private final JdbcClient db; private final ObjectMapper json; public PaymentController(JdbcClient db,ObjectMapper json){this.db=db;this.json=json;}
 public record Create(@NotNull UUID invoiceId,@NotNull @DecimalMin("0.01") BigDecimal amount,@NotBlank @Pattern(regexp="[A-Z]{3}") String currency,@NotBlank String idempotencyKey){}
 public record Payment(UUID id,UUID invoiceId,BigDecimal amount,String currency,String status,Instant receivedAt){}
 @PostMapping @Transactional public ResponseEntity<Payment> create(@Valid @RequestBody Create r) throws Exception {var existing=db.sql("select id,invoice_id,amount,currency,status,received_at from payments where idempotency_key=:key").param("key",r.idempotencyKey()).query(Payment.class).optional(); if(existing.isPresent()) return ResponseEntity.ok(existing.get()); var v=new Payment(UUID.randomUUID(),r.invoiceId(),r.amount(),r.currency(),"RECEIVED",Instant.now()); db.sql("insert into payments values(:id,:invoice,:amount,:currency,:status,:key,:at)").param("id",v.id()).param("invoice",v.invoiceId()).param("amount",v.amount()).param("currency",v.currency()).param("status",v.status()).param("key",r.idempotencyKey()).param("at",java.sql.Timestamp.from(v.receivedAt())).update(); db.sql("insert into outbox_events values(:id,'payment',:aggregate,'PaymentReceived',cast(:payload as jsonb),:at)").param("id",UUID.randomUUID()).param("aggregate",v.id()).param("payload",json.writeValueAsString(v)).param("at",java.sql.Timestamp.from(v.receivedAt())).update(); return ResponseEntity.created(URI.create("/api/payments/"+v.id())).body(v);}
}
